#pragma once

#include "config_types.hpp"
#include <string_view>

namespace config {

// Reads the bridge.json file generated by the discovery tool.
// Throws if the file cannot be opened or contains a parse error.
// Only entries with "enabled": true are loaded into the config.
[[nodiscard]]
BridgeConfig load_bridge_config(std::string_view path);

// Parses and validates bridge.json content (used by load_bridge_config).
// Throws std::runtime_error on a parse error or an invalid value.
[[nodiscard]]
BridgeConfig parse_bridge_config(std::string_view content);

} // namespace config
